"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[8926],{8926(e,n,i){i.d(n,{content:()=>d,description:()=>s,keywords:()=>a,title:()=>t});i(5043);var r=i(579);const t="94% der Studierenden nutzen KI, und das ist nicht das Problem",s="Die HEPI-Umfrage 2026 zeigt nahezu universelle KI-Nutzung unter britischen Studierenden. Die eigentliche Krise liegt nicht in der KI-Nutzung selbst, sondern darin, dass wir weiterhin Ergebnisse bewerten, die KI leicht produzieren kann. Prozessbasierte Bewertung bietet eine L\xf6sung.",a=["KI in der Bildung","Studierende KI-Nutzung","Bewertungskrise","prozessbasierte Bewertung","KI-sichere Bewertung","virtuelles Labor Bewertung","HEPI KI-Umfrage 2026","KI-Erkennung Fehler"],d=(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)("p",{children:["Die Umfrage des Higher Education Policy Institute zur generativen KI unter Studierenden 2026 wurde letzte Woche mit einer Statistik ver\xf6ffentlicht, die Schlagzeilen machte: 94% der britischen Studierenden nutzen mittlerweile generative KI zur Unterst\xfctzung bei bewerteten Arbeiten (",(0,r.jsx)("a",{href:"https://www.hepi.ac.uk/reports/student-generative-ai-survey-2026/",target:"_blank",rel:"noopener noreferrer",children:"HEPI, 2026"}),"). Die Reaktion war vorhersehbar. Einige Kommentatoren beklagten die akademische Integrit\xe4t. Andere forderten strengere Erkennungstools. Einige wenige schlugen vor, einfach die Niederlage zu akzeptieren und KI alles schreiben zu lassen."]}),(0,r.jsx)("p",{children:"All diese Reaktionen verfehlen den Punkt. Die 94%-Zahl ist kein Beweis daf\xfcr, dass Studierende massenhaft betr\xfcgen. Sie ist ein Beweis daf\xfcr, dass traditionelle Bewertung defekt ist, und das schon seit einiger Zeit. Wir haben Ergebnisse bewertet, die KI jetzt m\xfchelos produzieren kann, und uns dann gewundert, wenn Studierende KI nutzen, um sie zu produzieren. Das Problem sind nicht die Studierenden. Das Problem ist, dass wir die falschen Dinge bewertet haben."}),(0,r.jsx)("h2",{children:"Was zeigt die HEPI-Umfrage tats\xe4chlich?"}),(0,r.jsx)("p",{children:'Der HEPI-Bericht, durchgef\xfchrt von Savanta im Dezember 2025 mit 1.054 Vollzeit-Studierenden in Gro\xdfbritannien, zeigt ein nuancierteres Bild als die Schlagzeile suggeriert. Ja, 94% nutzen KI zur Unterst\xfctzung bei bewerteten Arbeiten. Aber "Unterst\xfctzung" umfasst ein breites Spektrum: Zusammenfassen dichter Lekt\xfcre, Erstellen von Entwurfsgliederungen, Erkl\xe4ren schwieriger Konzepte und Grammatikpr\xfcfung. Nur 12% geben an, KI-generierten Text direkt in ihre Einreichungen aufzunehmen, gegen\xfcber 8% im Vorjahr.'}),(0,r.jsx)("p",{children:'Die qualitativen Antworten sind besonders aufschlussreich. Ein Studierender erkl\xe4rte: "KI-Tools erm\xf6glichten es mir, dichte Lekt\xfcre schnell zusammenzufassen und Entw\xfcrfe oder Gliederungen f\xfcr Aufgaben zu erstellen, was Stunden m\xfchsamer Arbeit sparte und mir erm\xf6glichte, mich auf kritische Analyse und tieferes Verst\xe4ndnis zu konzentrieren." Ein anderer gab einfach zu: "Ich benutze mein Gehirn \xfcberhaupt nicht." Die HEPI-Autoren bemerken den auff\xe4lligen Kontrast: "Es gibt einen Unterschied zwischen einem Studierenden, der KI nutzt, um sein Lernen voranzutreiben, und einem Studierenden, der sein Lernen an KI auslagert."'}),(0,r.jsx)("p",{children:'Diese Unterscheidung ist wichtig. Der erste Studierende nutzt KI als kognitives Ger\xfcst und setzt mentale Ressourcen f\xfcr h\xf6herwertige Denkprozesse frei. Der zweite erlebt das, was die OECD "kognitives Auslagern" nennt, wobei er die KI denken l\xe4sst und den f\xfcr echtes Lernen notwendigen Kampf verpasst. Beide Verhaltensweisen werden als "KI-Nutzung" registriert, aber ihre bildungsbezogenen Auswirkungen sind gegens\xe4tzlich.'}),(0,r.jsx)("h2",{children:"Warum Erkennung dieses Problem nicht l\xf6sen kann"}),(0,r.jsx)("p",{children:"Die instinktive Reaktion auf steigende KI-Nutzung ist die Verbesserung der Erkennung. Wenn Studierende KI unangemessen nutzen, erwischen Sie sie. Aber dieser Ansatz ist gescheitert, scheitert und wird aus gut dokumentierten Gr\xfcnden weiterhin scheitern."}),(0,r.jsxs)("p",{children:["Unabh\xe4ngige Analysen haben ergeben, dass KI-Erkennungstools Falsch-Positiv-Raten zwischen 5% und 20% produzieren, was bedeutet, dass echte Studierendenarbeit routinem\xe4\xdfig als maschinengeneriert markiert wird (",(0,r.jsx)("a",{href:"https://nmllplaw.com/blog/when-ai-gets-you-accused-what-to-do-if-your-school-says-you-used-chatgpt/",target:"_blank",rel:"noopener noreferrer",children:"Nesenoff & Miltenberg, 2025"}),'). Die Konsequenzen sind nicht abstrakt. Im Jahr 2024 beschuldigte die Australian Catholic University f\xe4lschlicherweise etwa 1.500 Studierende auf Basis von Turnitins KI-Detektor. Studierende verloren Stellen als Pflegekr\xe4fte nach dem Studium. Transkripte wurden monatelang als "Ergebnisse zur\xfcckgehalten" markiert. Einige wurden gezwungen, ihren gesamten Internet-Browserverlauf zu \xfcbergeben, um ihre Unschuld zu beweisen.']}),(0,r.jsx)("p",{children:'Diese Tools sind besonders unzuverl\xe4ssig f\xfcr nicht-muttersprachliche Englischsprecher und neurodivergente Studierende, deren Schreibmuster nat\xfcrlich von dem abweichen k\xf6nnen, was Algorithmen als "menschliches Schreiben" erwarten. Ein Studierender der Yale School of Management klagte 2025 wegen unrechtm\xe4\xdfiger Suspendierung, nachdem GPTZero seine Pr\xfcfung markiert hatte, und f\xfchrte Diskriminierung gegen nicht-muttersprachliche Englischsprecher an. Das Erkennungs-Wettr\xfcsten ist nicht nur wirkungslos; es schadet aktiv den Studierenden, die es zu sch\xfctzen vorgibt.'}),(0,r.jsx)("p",{children:"Selbst wenn Erkennung funktioniert, behandelt sie nur das Symptom. Ein Studierender, der die Erkennung erfolgreich umgeht, hat trotzdem nichts aus der Aufgabe gelernt. Ein Studierender, der erwischt wird, wurde bestraft, aber die zugrundeliegende Anreizstruktur bleibt unver\xe4ndert. Solange wir Ergebnisse bewerten, die KI produzieren kann, schaffen wir Anreize f\xfcr Studierende, KI zu nutzen, um sie zu produzieren. Erkennung behandelt das Verhalten als moralisches Versagen, wenn es tats\xe4chlich eine rationale Reaktion auf falsch ausgerichtete Anreize ist."}),(0,r.jsx)("h2",{children:"Das eigentliche Problem: Bewertung von Ergebnissen, die kein menschliches Denken mehr erfordern"}),(0,r.jsx)("p",{children:"Der traditionelle Aufsatz, der Laborbericht, der Aufgabensatz: Diese Bewertungsformate entwickelten sich, als ihre Produktion anhaltende kognitive Anstrengung erforderte. Wenn Sie ein gut strukturiertes Argument \xfcber Photosynthese wollten, mussten Sie Photosynthese verstehen. Wenn Sie eine koh\xe4rente Analyse von Titrationsergebnissen wollten, mussten Sie die Titration durchf\xfchren und die Daten durchdenken. Das Ergebnis diente als vern\xfcnftiger Beweis f\xfcr den Prozess."}),(0,r.jsx)("p",{children:"Diese Korrelation ist zerbrochen. Ein Studierender kann jetzt eine KI auffordern, einen ausgekl\xfcgelten Aufsatz mit Zitaten in weniger als einer Minute zu generieren. Sie k\xf6nnen einen Laborbericht mit plausiblen Beobachtungen, angemessener Fehleranalyse und gut begr\xfcndeten Schlussfolgerungen anfordern, ohne Ger\xe4te zu ber\xfchren. Das Ergebnis sieht korrekt aus, weil KI synthetisieren kann, wie korrekte Ergebnisse aussehen. Aber der Studierende hat keine der F\xe4higkeiten entwickelt, die die Aufgabe vermitteln sollte."}),(0,r.jsx)("p",{children:"Dies ist kein neues Problem. Studierende haben immer Wege gefunden, Bewertungen abzuk\xfcrzen: Kopieren von Vorjahren, Aufteilen der Arbeit unter Studiengruppen, Online-Kauf von Aufs\xe4tzen. KI hat einfach die Abk\xfcrzung demokratisiert und sie allen zug\xe4nglich gemacht, nicht nur denen mit Ressourcen oder Verbindungen. Das Ausma\xdf hat sich ge\xe4ndert, aber das zugrundeliegende Problem, dass wir vom Prozess losgel\xf6ste Ergebnisse bewerten, existiert seit Jahrzehnten."}),(0,r.jsx)("h2",{children:"Wie sieht KI-sichere Bewertung aus?"}),(0,r.jsxs)("p",{children:['Der OECD Digital Education Outlook 2026 beantwortete diese Frage explizit: "Anstatt die Abschlussarbeit zu benoten, sollten Lehrkr\xe4fte bewerten, wie ein Studierender mit KI interagiert hat, wie er deren Ausgabe kritisiert hat und wie er seine Ideen im Laufe der Zeit verfeinert hat" (',(0,r.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"OECD, 2026"}),"). Dies ist prozessorientierte Bewertung: nicht bewerten, was Studierende produzieren, sondern wie sie sich mit dem Lernen besch\xe4ftigen, um es zu produzieren."]}),(0,r.jsx)("p",{children:"In der Praxis bedeutet dies, den Prozess selbst zu erfassen. Wenn ein Studierender ein Problem durcharbeitet, welche Entscheidungen trifft er? Wenn er auf Schwierigkeiten st\xf6\xdft, wie reagiert er? Wenn sein erster Ansatz scheitert, passt er sich an oder gibt er auf? Diese Fragen zielen auf das ab, was Bildung tats\xe4chlich entwickeln soll: Denkf\xe4higkeiten, Probleml\xf6sungskompetenz und die F\xe4higkeit, aus Fehlern zu lernen."}),(0,r.jsx)("p",{children:"Die Laborwissenschaft bietet ein besonders klares Beispiel. Man kann nicht mit KI durch Pipettiertechnik navigieren. Man kann ChatGPT nicht auffordern, Feinmotorik zu entwickeln, die F\xe4higkeit, subtile Farbver\xe4nderungen zu beobachten, oder das Instinkt daf\xfcr, wenn ein Experiment sich falsch anf\xfchlt. Diese F\xe4higkeiten existieren im K\xf6rper und entwickeln sich durch \xdcbung. Ein Studierender, der zuschaut, wie KI einen perfekten Laborbericht generiert, hat nichts \xfcber die Arbeit im Labor gelernt."}),(0,r.jsx)("h2",{children:"Wie virtuelle Labore Prozessbewertung erm\xf6glichen"}),(0,r.jsx)("p",{children:"Bei WhimsyLabs ist prozessorientierte Bewertung keine nachtr\xe4gliche Reaktion auf KI. Es ist die Art, wie wir unsere Plattform von Anfang an entworfen haben. Unsere virtuellen Labore erfassen jede Aktion, die ein Studierender vornimmt: welche Ger\xe4te er ausw\xe4hlt, in welcher Reihenfolge er Schritte ausf\xfchrt, wie er auf unerwartete Ergebnisse reagiert und wie sich seine Technik im Laufe der Zeit verbessert. Diese Interaktionsprotokollierung erstellt einen detaillierten Bericht \xfcber wissenschaftliches Denken in Aktion."}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Aktionsprotokollierung"})," ist die Grundlage. Wenn ein Studierender eine L\xf6sung pipettiert, verfolgen wir seine Technik: den Winkel, in dem er die Pipette h\xe4lt, die Geschwindigkeit, mit der er dosiert, ob er die Spitze vorbefeuchtet. Wenn er die Temperatur misst, zeichnen wir nicht nur den Endwert auf, sondern wann er ihn genommen hat, wie viele Messungen er durchgef\xfchrt hat und ob er auf das Gleichgewicht gewartet hat. Diese granularen Details zeigen, ob ein Studierender ordnungsgem\xe4\xdfe Laborgewohnheiten entwickelt oder nur die Bewegungen durchf\xfchrt."]}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Technikbewertung"})," baut auf der Aktionsprotokollierung auf, um Verfahrenskompetenz zu bewerten. Ein Studierender, der den richtigen Endpunkt bei einer Titration durch schlampige Technik erreicht, erh\xe4lt anderes Feedback als einer, dessen Technik pr\xe4zise war, aber der die Molarit\xe4t falsch berechnet hat. Beide m\xfcssen sich verbessern, aber auf unterschiedliche Weise. Traditionelle Bewertung, die sich nur auf die Endantwort konzentriert, kann zwischen ihnen nicht unterscheiden."]}),(0,r.jsxs)("p",{children:[(0,r.jsx)("strong",{children:"Expertenpfad-Vergleich"})," setzt Studierendenverhalten in Kontext. Wir haben kartiert, wie Expertenwissenschaftler h\xe4ufige Experimente angehen und dabei die Entscheidungsb\xe4ume und Probleml\xf6sungsmuster identifiziert, die kompetentes wissenschaftliches Denken charakterisieren. Wenn der Ansatz eines Studierenden erheblich von Expertenpfaden abweicht, signalisiert dies eine Gelegenheit f\xfcr gezielte Anleitung. Wenn sein Ansatz mit der Expertenlogik \xfcbereinstimmt, selbst wenn er zu einer falschen Schlussfolgerung kommt, deutet dies darauf hin, dass sich sein wissenschaftliches Denken angemessen entwickelt."]}),(0,r.jsx)("h2",{children:"Die Bewertungskrise ist auch eine Chance"}),(0,r.jsx)("p",{children:"Die HEPI-Umfrage zeigt etwas, das jeden P\xe4dagogen beunruhigen sollte: Fast zwei Drittel der Studierenden (65%) sagen, dass sich die Bewertung als Reaktion auf KI erheblich ver\xe4ndert hat, und viele artikulieren Angst vor falschen Anschuldigungen wegen Fehlverhaltens. Studierende leben in einer \xdcberwachungsumgebung, in der ihre authentische Arbeit als betr\xfcgerisch markiert werden k\xf6nnte, w\xe4hrend KI-unterst\xfctzte Arbeit unentdeckt bleiben k\xf6nnte. Die Anreize sind pervers."}),(0,r.jsx)("p",{children:"Aber dieselbe Umfrage zeigt einen Weg nach vorn. Studierende sehen KI-F\xe4higkeiten \xfcberw\xe4ltigend als wesentlich an, wobei 68% glauben, dass diese F\xe4higkeiten notwendig sind, um in der heutigen Welt erfolgreich zu sein. Sie versuchen nicht zu betr\xfcgen. Sie versuchen, F\xe4higkeiten zu entwickeln, die sie korrekt als wichtig wahrnehmen. Das Problem ist, dass aktuelle Bewertungsstrukturen sie zwingen, zwischen der Entwicklung von KI-Kompetenz und dem Nachweis von Fachwissen zu w\xe4hlen, wenn beides gleichzeitig m\xf6glich sein sollte."}),(0,r.jsx)("p",{children:"Prozessorientierte Bewertung l\xf6st diese Spannung. Wenn wir bewerten, wie Studierende denken, statt was sie produzieren, wird KI zu einem Werkzeug statt zu einer Bedrohung. Studierende k\xf6nnen KI nutzen, um Lekt\xfcre zusammenzufassen, Entwurfsgliederungen zu erstellen oder ihre Argumentation zu \xfcberpr\xfcfen, w\xe4hrend sie weiterhin auf die kognitive Arbeit bewertet werden, die z\xe4hlt: Hypothesen bilden, Daten interpretieren, sich an unerwartete Ergebnisse anpassen und praktische Laborf\xe4higkeiten entwickeln, die keine KI replizieren kann."}),(0,r.jsx)("h2",{children:"Was das f\xfcr die naturwissenschaftliche Bildung bedeutet"}),(0,r.jsx)("p",{children:"Die naturwissenschaftliche Bildung steht vor einer besonderen Herausforderung, da Laborf\xe4higkeiten f\xfcr die Disziplin zentral sind. Ein Studierender, der nie eine Pipette gehalten, ein Mikroskop eingestellt oder eine chemische Reaktion beobachtet hat, kann nicht behaupten, Naturwissenschaft in irgendeinem bedeutsamen Sinne zu verstehen. Doch traditionelle Laborbewertung, die sich auf schriftliche Berichte konzentriert, war immer anf\xe4llig f\xfcr Abk\xfcrzungen. KI hat diese Anf\xe4lligkeit einfach unm\xf6glich zu ignorieren gemacht."}),(0,r.jsx)("p",{children:"Die L\xf6sung ist nicht, KI aus der naturwissenschaftlichen Bildung zu verbannen. Es geht darum zu bewerten, was KI nicht kann: die praktischen F\xe4higkeiten, die Verfahrenskompetenz, die F\xe4higkeit, auf Echtzeit-Experimentierherausforderungen zu reagieren. Virtuelle Labore, die Prozessdaten erfassen, machen dies in gro\xdfem Ma\xdfstab m\xf6glich. Das Interaktionsprotokoll eines Studierenden liefert reichhaltigere Beweise f\xfcr seine wissenschaftliche Entwicklung als jeder schriftliche Bericht es k\xf6nnte, und es kann von keiner KI gef\xe4lscht werden."}),(0,r.jsx)("p",{children:'Die HEPI-Autoren schlie\xdfen, dass "Institutionen eine entscheidende Rolle dabei spielen, sicherzustellen, dass KI das Lernen verbessert statt es zu vermindern." Sie empfehlen strukturierte KI-Einf\xfchrung, Lehrplan\xe4nderungen zur expliziten Vermittlung von KI-F\xe4higkeiten und klare bewertungsspezifische Leitlinien. All das ist wichtig. Aber die grundlegendste erforderliche \xc4nderung ist das \xdcberdenken dessen, was wir \xfcberhaupt bewerten.'}),(0,r.jsx)("p",{children:"Vierundneunzig Prozent der Studierenden, die KI nutzen, sind keine Krise. Es ist ein Signal, dass sich Bewertung weiterentwickeln muss. Die Werkzeuge existieren. Die Forschung unterst\xfctzt es. Die einzige Frage ist, ob sich die Bildung anpasst oder weiterhin einen Erkennungskrieg f\xfchrt, den sie bereits verloren hat."}),(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)("h2",{children:"Verwandte Artikel"}),(0,r.jsxs)("ul",{children:[(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/oecd-process-oriented-assessment-validation",children:"OECD sagt: Bewerten Sie den Prozess, nicht das Produkt"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/ai-text-grading-fails-process-assessment-works",children:"Warum KI-Textbewertung scheitert und Prozessbewertung funktioniert"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/process-based-lab-assessment-future",children:"Den Prozess bewerten, nicht die Antwort: Die Zukunft der Laborbewertung"})}),(0,r.jsx)("li",{children:(0,r.jsx)("a",{href:"/de/blog/ai-assessment-crisis-solution",children:"KI und die Bewertungskrise: Eine praktische L\xf6sung"})})]})]}),(0,r.jsxs)("div",{className:"references-section",children:[(0,r.jsx)("h3",{children:"Referenzen"}),(0,r.jsxs)("ul",{className:"references-list",children:[(0,r.jsxs)("li",{children:["Higher Education Policy Institute (HEPI). (2026). Student Generative AI Survey 2026. HEPI Report 199."," ",(0,r.jsx)("a",{href:"https://www.hepi.ac.uk/reports/student-generative-ai-survey-2026/",target:"_blank",rel:"noopener noreferrer",children:"https://www.hepi.ac.uk/reports/student-generative-ai-survey-2026/"})]},"ref-1"),(0,r.jsxs)("li",{children:["Nesenoff & Miltenberg LLP. (2025). When AI Gets You Accused: What to Do if Your School Says You Used ChatGPT."," ",(0,r.jsx)("a",{href:"https://nmllplaw.com/blog/when-ai-gets-you-accused-what-to-do-if-your-school-says-you-used-chatgpt/",target:"_blank",rel:"noopener noreferrer",children:"https://nmllplaw.com/blog/when-ai-gets-you-accused-what-to-do-if-your-school-says-you-used-chatgpt/"})]},"ref-2"),(0,r.jsxs)("li",{children:["OECD. (2026). OECD Digital Education Outlook 2026: Exploring Effective Uses of Generative AI in Education. OECD Publishing."," ",(0,r.jsx)("a",{href:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html",target:"_blank",rel:"noopener noreferrer",children:"https://www.oecd.org/en/publications/oecd-digital-education-outlook-2026_062a7394-en.html"})]},"ref-3")]})]})]})}}]);
